    tasks[cell('Tasks', f'K{r}')] = cell('Tasks', f'L{r}')

deps = []
for r in range(38, 44):
    deps.append((cell('Dependencies', f'K{r}'), cell('Dependencies', f'L{r}')))

# Find all tasks
all_tasks = list(tasks.keys())
