# Build graph
adj = {t: [] for t in all_tasks}
pred = {t: [] for t in all_tasks}
for succ, pred_task in deps:
    adj[pred_task].append(succ)
    pred[succ].append(pred_task)

# Compute ES, EF using CPM
es = {t: 0 for t in all_tasks}
ef = {t: tasks[t] for t in all_tasks}

# Topological sort order
visited = set()
order = []
def visit(t):
    if t in visited: return
    visited.add(t)
    for p in pred[t]:
        visit(p)
    order.append(t)

for t in all_tasks:
    visit(t)

for t in order:
    if pred[t]:
        es[t] = max(ef[p] for p in pred[t])
    else:
        es[t] = 0
    ef[t] = es[t] + tasks[t]

result = max(ef.values())

